	private static BindingSetAssignment values(String name, IRI value) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, value);
		assignment.setBindingSets(List.of(row));
		return assignment;
	}

	private static List<BindingSet> evaluate(QueryRoot expression, BindingSet bindings) throws Exception {
		return evaluate(expression, bindings, new EmptyTripleSource());
	}

	private static List<BindingSet> evaluate(QueryRoot expression, BindingSet bindings, TripleSource source)
			throws Exception {
		EvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		List<BindingSet> result = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, bindings)) {
			while (iteration.hasNext()) {
				result.add(iteration.next());
			}
		}
		return result;
	}

	private static ListMemberOperator in(String variable, Value... values) {
		ListMemberOperator condition = new ListMemberOperator();
		condition.addArgument(Var.of(variable));
		for (Value value : values) {
			condition.addArgument(new ValueConstant(value));
		}
		return condition;
	}

	private static BindingSetAssignment immutableValues(String name, Value... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of(name));
		List<BindingSet> rows = new ArrayList<>();
		for (Value value : values) {
			rows.add(new ListBindingSet(List.of(name), value));
		}
		assignment.setBindingSets(List.copyOf(rows));
		return assignment;
	}

	private static StatementPattern pattern(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("predicate", predicate), Var.of(object));
	}

	private static final class CountingSource implements TripleSource {
		private final Map<AccessKey, List<Statement>> statements = new HashMap<>();
		private final Map<IRI, Integer> lookups = new HashMap<>();

		void add(Resource subject, IRI predicate, Value object) {
			statements.computeIfAbsent(new AccessKey(subject, predicate), ignored -> new ArrayList<>())
					.add(VF.createStatement(subject, predicate, object));
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			lookups.merge(predicate, 1, Integer::sum);
			List<Statement> candidates = subject == null
					? statements.entrySet()
							.stream()
							.filter(entry -> predicate.equals(entry.getKey().predicate()))
							.flatMap(entry -> entry.getValue().stream())
							.toList()
					: statements.getOrDefault(new AccessKey(subject, predicate), List.of());
			return new CloseableIteratorIteration<>(candidates.stream()
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		private record AccessKey(Resource subject, IRI predicate) {
		}
	}
